(globalThis.CATALOGUE_RECORD_CHUNKS??=Object.create(null))[674]={"source_order":674,"notes":["The superscript letter after 337 is read as 'b'. This is consistent with the folio label.","Very faint marks may be obscured by the show-through, but none were found that read the right way round.","All faint writing across the body and the left margin is mirror-reversed show-through from the recto, fol. 337. Its line positions match that page's Marathi and Bengali entries, for example the reversed shelfmarks and the 'n.d.' extent columns, and the 'iii. Bengali' heading at about mid-page. It is not treated as target-page text.","No independent writing was found on this verso apart from the folio number.","The page was reviewed in the overview and in all six native tiles. Apart from the folio number, it is blank of independent writing.","All faint writing across the body and the left margin is mirror-reversed show-through from the recto, fol. 337 (source order 673). Examples are the reversed shelfmark and 'n.d.' extent columns, and the 'iii. Bengali' heading at about mid-page. It is not transcribed as target-page text.","Non-text marks with no textual content: a small dark ink spot near the top edge at about [1855,315,40,40]; a short oblique stroke near the top edge at about [1260,320,40,80]; a small dash or tick at the vertical margin rule at about [860,2460,70,20]; a smudge near the bottom edge at about [1040,4730,140,40]; scattered small dots and specks, including some at the left (gutter) edge.","Ruled lines and the vertical margin rule are printed ruling, not catalogue content."],"records":[{"id":"css-prod-0674-r001","local_id":"r001","source_order":674,"folio":"337b","folio_label":"fol. 337b","sequence":1,"page_id":"47338143-bc0f-4537-be6f-2d5e7f2d0f66","kind":"other","record_type":"non_catalogue_text","source_model_record_type":"non_catalogue_text","subtype":"folio_number","shelfmark":"","titleLiteral":"","titleNormalized":"","displayTitle":"Catalogue text","authorOrSource":"","source":"","subject":"","subjectGroup":"","date":"","extent":"","lines":"","script":"","incipit":"","transcription":"337^b.","annotations":["Handwritten folio number at the top left of the left margin column, in darker ink or pencil than the show-through.","The letter after '337' is written superscript and is followed by a point."],"uncertainties":["The superscript letter is read as 'b'. This agrees with the supplied folio label 'fol. 337b'."],"focused_readings":[],"reviewNotes":[],"editorialNotes":[],"relationships":[],"editorial_context":[],"block_ids":["b001"],"locations":[{"block_id":"b001","bbox":[455,355,175,150]}],"isCancelled":false,"needsReview":true,"human_verified":false,"verification_status":"machine_reviewed","change_audit":[],"sourceCitationURL":"https://iiif.bodleian.ox.ac.uk/iiif/canvas/47338143-bc0f-4537-be6f-2d5e7f2d0f66.json","auditPath":"audit/pages/0674.json","attachedNotes":[],"resolvedRelationships":[],"attachedRecords":[]}]};
